#pragma once
#include "source_stored_zip_candidate.h"
#include <filesystem>
#include <fstream>
#include <memory>
#ifndef NOMINMAX
#define NOMINMAX
#endif
#include <windows.h>
// Explicit priority-ordered loose-directory/BSP mounts; no writes/extraction,
// Steam startup, VPK, implicit pak ZIPs, or archive decompression. BSP archives
// become owned immutable snapshots; loose files are read afresh per request.
struct SourceMaterialSourceMountCandidate {std::filesystem::path path;std::string pathID="GAME";};
struct SourceMaterialSourceFileCandidate {std::string logicalPath,pathID;std::filesystem::path mount;bool packed=false;size_t mountIndex=0;std::vector<uint8_t>bytes;};
class SourceMaterialSourceProviderCandidate {
 struct Mount {std::filesystem::path path;std::string id;std::shared_ptr<const SourceStoredZipCandidate>pak;};std::vector<Mount>mounts;
 static std::string id(std::string value){if(value.empty()||value.size()>64)throw std::runtime_error("material mount path-ID extent");for(unsigned char c:value)if(!((c>='a'&&c<='z')||(c>='A'&&c<='Z')||(c>='0'&&c<='9')||c=='_'))throw std::runtime_error("material mount path-ID encoding");return sourceMaterialPatchLowerCandidate(value);}
 static bool missing(const std::error_code&e){return e==std::errc::no_such_file_or_directory||e==std::errc::not_a_directory;}
 static void directory(const std::filesystem::path&path){std::error_code ec;auto status=std::filesystem::symlink_status(path,ec);if(ec){if(missing(ec))return;throw std::system_error(ec,"material mount status");}if(!std::filesystem::exists(status))return;if(std::filesystem::is_symlink(status)||!std::filesystem::is_directory(status))throw std::runtime_error("material loose mount type");for(const auto&e:std::filesystem::directory_iterator(path)){const auto ext=sourceMaterialPatchLowerCandidate(e.path().extension().string());if(ext==".zip"||ext==".vpk"||ext==".pak")throw std::runtime_error("implicit material archive search not implemented");}}
 static uint32_t word(const std::vector<uint8_t>&data,size_t p){if(p>data.size()||data.size()-p<4)throw std::runtime_error("BSP pak header extent");return uint32_t(data[p])|(uint32_t(data[p+1])<<8)|(uint32_t(data[p+2])<<16)|(uint32_t(data[p+3])<<24);}
 static std::vector<uint8_t>readRange(std::ifstream&file,size_t at,size_t bytes){std::vector<uint8_t>out(bytes);file.seekg(std::streamoff(at));if(!file)throw std::runtime_error("material source seek");if(bytes&&!file.read(reinterpret_cast<char*>(out.data()),std::streamsize(bytes)))throw std::runtime_error("material source read truncated");return out;}
 static size_t fileSize(std::ifstream&file){file.seekg(0,std::ios::end);auto end=file.tellg();if(end<0||uint64_t(end)>uint64_t(SIZE_MAX))throw std::runtime_error("material source file extent");return size_t(end);}
 static std::shared_ptr<const SourceStoredZipCandidate>bsp(const std::filesystem::path&path){std::ifstream file(path,std::ios::binary);if(!file)throw std::runtime_error("BSP material source open");const auto size=fileSize(file);if(size<1036)throw std::runtime_error("BSP material source header");auto header=readRange(file,0,1036);if(word(header,0)!=0x50534256||word(header,4)!=20)throw std::runtime_error("BSP material source version");const size_t p=8+40*16,offset=word(header,p),bytes=word(header,p+4);if(word(header,p+8)||word(header,p+12)||offset>size||bytes>size-offset||bytes>(1u<<26))throw std::runtime_error("BSP material pak lump extent/encoding");std::vector<uint8_t>data;if(bytes)data=readRange(file,offset,bytes);else{data.resize(22);data[0]=0x50;data[1]=0x4b;data[2]=5;data[3]=6;}if(fileSize(file)!=size)throw std::runtime_error("BSP material source changed size");return std::make_shared<const SourceStoredZipCandidate>(std::move(data));}
public:
 explicit SourceMaterialSourceProviderCandidate(const std::vector<SourceMaterialSourceMountCandidate>&ordered){if(ordered.empty()||ordered.size()>128)throw std::runtime_error("material source mount extent");std::set<std::pair<std::string,std::string>>seen;for(const auto&entry:ordered){if(!entry.path.is_absolute())throw std::runtime_error("absolute material source mount required");Mount mount;mount.path=entry.path.lexically_normal();if(mount.path.filename().empty()&&mount.path!=mount.path.root_path())mount.path=mount.path.parent_path();mount.id=id(entry.pathID);if(!seen.insert({sourceMaterialPatchLowerCandidate(mount.path.generic_string()),mount.id}).second)throw std::runtime_error("duplicate material source mount");if(sourceMaterialPatchLowerCandidate(mount.path.extension().string())==".bsp")mount.pak=bsp(mount.path);else directory(mount.path);mounts.push_back(std::move(mount));}}
 std::optional<SourceMaterialSourceFileCandidate>read(const std::string&logical,const std::string&pathID="GAME")const{
  const auto key=sourceMaterialKeyValuesPathCandidate(logical),queryID=id(pathID);for(size_t index=0;index<mounts.size();++index){const auto&m=mounts[index];if(m.id!=queryID)continue;SourceMaterialSourceFileCandidate result;result.logicalPath=key;result.pathID=m.id;result.mount=m.path;result.packed=bool(m.pak);result.mountIndex=index;if(m.pak){auto bytes=m.pak->read(key);if(!bytes)continue;result.bytes=std::move(*bytes);return result;}
   const auto path=m.path/std::filesystem::path(key);std::error_code ec;auto status=std::filesystem::symlink_status(path,ec);if(ec){if(missing(ec))continue;throw std::system_error(ec,"material source status");}if(!std::filesystem::exists(status))continue;if(std::filesystem::is_symlink(status)||!std::filesystem::is_regular_file(status))throw std::runtime_error("material source is not a regular file");/* Logical paths have no remaining parent/root components. Check every child for reparse redirection without canonical(), which requires directory-handle access not available on all readable game drives. */auto checked=m.path;for(const auto&part:std::filesystem::path(key)){checked/=part;const DWORD attributes=GetFileAttributesW(checked.c_str());if(attributes==INVALID_FILE_ATTRIBUTES)throw std::system_error(int(GetLastError()),std::system_category(),"material source attributes");if(attributes&FILE_ATTRIBUTE_REPARSE_POINT)throw std::runtime_error("material source reparse path unsupported");}std::ifstream file(path,std::ios::binary);if(!file)throw std::runtime_error("material source open");auto size=fileSize(file);if(size>(1u<<24))throw std::runtime_error("material source exceeds checked file extent");result.bytes=readRange(file,0,size);if(fileSize(file)!=size)throw std::runtime_error("material source changed size");return result;
  }return {};
 }
 SourceMaterialKeyValuesSourceCandidate materialSource(const std::string&pathID="GAME")const{const auto queryID=id(pathID);return [owned=*this,queryID](const std::string&logical)->std::optional<std::string>{auto file=owned.read(logical,queryID);if(!file)return {};return std::string(file->bytes.begin(),file->bytes.end());};}
};
